/// <summary>
/// Class entry point. The system will call this method when a designated menu
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    HcmWorker   hcmWorker;
    int         row = 1;

    // Wichtig: EPPlus-Initialisierung ist in neueren Versionen teils nötig,
    // ggf. hier Setup-Code ergänzen (Lizenzkonfiguration o.Ä.), falls in deinem System erforderlich.

    using (System.IO.MemoryStream memoryStream = new System.IO.MemoryStream())
    {
        using (ExcelPackage package = new ExcelPackage(memoryStream))
        {
            // Neues Worksheet
            var workbook   = package.get_Workbook();
            var worksheets = workbook.get_Worksheets();
            var worksheet  = worksheets.Add("NonDeletableHcmWorkers");
            var cells      = worksheet.get_Cells();

            OfficeOpenXml.ExcelRange cell;

            // Header-Zeile
            cell = cells.get_Item(row, 1); cell.set_Value("RecId");
            cell = cells.get_Item(row, 2); cell.set_Value("PersonnelNumber");
            cell = cells.get_Item(row, 3); cell.set_Value("FirstName");
            cell = cells.get_Item(row, 4); cell.set_Value("LastName");
            cell = cells.get_Item(row, 5); cell.set_Value("Infolog");

            // ggf. weitere Spalten hier ergänzen (Name, Firma, Status, ...)

            row++;

            // Alle HcmWorker durchlaufen
            while select hcmWorker
            {
                boolean canDelete = true;
                int infologline = infolog.line();
                try
                {
                    // validateDelete() prüft DeleteActions / weitere Logik.
                    // Wenn false -> Löschen wird blockiert.
                    canDelete = hcmWorker.validateDelete();
                }
                catch (Exception::Error)
                {
                    // Wenn eine Exception kommt, werten wir das als "nicht löschbar"
                    canDelete = false;
                }

                // Nur die, die NICHT gelöscht werden dürfen, sollen in die Liste
                if (!canDelete)
                {

                    // RecId
                    cell = cells.get_Item(row, 1);
                    // RecId ist int64, wird als Zahl in Excel ausgegeben
                    cell.set_Value(hcmWorker.RecId);

                    // PersonnelNumber
                    cell = cells.get_Item(row, 2);
                    cell.set_Value(hcmWorker.PersonnelNumber);

                    // FirstName
                    cell = cells.get_Item(row, 3);
                    cell.set_Value(DirPersonName::find(hcmWorker.Person).FirstName);

                    //LastName
                    cell = cells.get_Item(row, 4);
                    cell.set_Value(DirPersonName::find(hcmWorker.Person).LastName);

                    if(infologline<infolog.line())
                    {
                        container conInfolog = infolog.copy(infologLine+1,infolog.line());
                        if(conInfolog != connull())
                        {
                            // Infolog
                            cell = cells.get_Item(row, 5);
                            // RecId ist int64, wird als Zahl in Excel ausgegeben
                            cell.set_Value(Info::infoCon2Str(conInfolog));
                        }
                    }
                    row++;
                }
            }

            // Datei in den Stream schreiben
            package.Save();

            // Excel zum Browser schicken
            File::SendFileToUser(memoryStream, 'HcmWorker_NonDeletable.xlsx');
        }
    }
}
